def is_strictly_increasing_digits(n):
    s = str(abs(n))
    return all(s[i] < s[i + 1] for i in range(len(s) - 1))

def normalize_to_percentage(counts):
    total = sum(counts.values())
    if total == 0:
        return {k: 0 for k in counts}
    return {k: round(100 * v / total, 2) for k, v in counts.items()}

def sanitize_filename_spaces(name):
    replaced = name.replace(" ", "_")
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-")
    return "".join(c for c in replaced if c in allowed)

def count_case_transitions(s):
    count = 0
    for a, b in zip(s, s[1:]):
        if a.isalpha() and b.isalpha():
            if (a.isupper() and b.islower()) or (a.islower() and b.isupper()):
                count += 1
    return count

def is_valid_identifier(s):
    import string
    if not s:
        return False
    allowed = string.ascii_letters + string.digits + '_'
    if s[0] not in string.ascii_letters + '_':
        return False
    return all(ch in allowed for ch in s)

def is_valid_env_var_name(s):
    if not s:
        return False
    if not ((s[0].isalpha() and s[0].isupper()) or s[0] == '_'):
        return False
    return all((c.isalpha() and c.isupper()) or c.isdigit() or c == '_' for c in s)

def is_valid_hex_color_alpha(s):
    if len(s) != 9 or s[0] != '#':
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s[1:])

def longest_border_length(s):
    n = len(s)
    if n == 0:
        return 0
    fail = [0] * n
    for i in range(1, n):
        j = fail[i - 1]
        while j > 0 and s[i] != s[j]:
            j = fail[j - 1]
        if s[i] == s[j]:
            j += 1
        fail[i] = j
    return fail[-1]

def is_valid_grid_reference(s):
    if len(s) < 2:
        return False
    if not s[0].isalpha() or not s[0].isupper():
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if len(digits) > 1 and digits[0] == '0':
        return False
    return 1 <= int(digits) <= 99

def count_letter_digit_symbol_groups(s):
    def cls(c):
        if c.isalpha():
            return 'L'
        if c.isdigit():
            return 'D'
        return 'O'
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if cls(s[i]) != cls(s[i - 1]):
            count += 1
    return count

def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    x = n
    while x > 0:
        digits.append(x % b)
        x //= b
    return digits == digits[::-1]

def chunk_fixed_size_pad(lst, k, pad):
    chunks = [lst[i:i+k] for i in range(0, len(lst), k)]
    if chunks and len(chunks[-1]) < k:
        chunks[-1] = chunks[-1] + [pad] * (k - len(chunks[-1]))
    return chunks

def sum_proper_divisors(n):
    if n <= 1:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total

def double_shift_day_delta(hh, mm, offset_minutes):
    total = hh * 60 + mm + offset_minutes
    day_delta = total // 1440
    if day_delta < 0:
        return "previous"
    elif day_delta > 0:
        return "next"
    return "same"

def sum_twin_primes_below(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    total = 0
    for p in range(2, n):
        if is_prime(p) and (is_prime(p - 2) or is_prime(p + 2)):
            total += p
    return total

def count_common_prefix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[i] == b[i]:
        i += 1
    return i

def is_valid_ipv6_full(s):
    groups = s.split(':')
    if len(groups) != 8:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    for g in groups:
        if not (1 <= len(g) <= 4):
            return False
        if not all(c in hexdigits for c in g):
            return False
    return True

import bisect
def bucket_by_range(nums, boundaries):
    d = {}
    for x in nums:
        b = bisect.bisect_right(boundaries, x)
        d[b] = d.get(b, 0) + 1
    return d

def filter_out_none_and_empty(lst):
    out = []
    for x in lst:
        if x is None:
            continue
        if isinstance(x, (str, list, tuple, dict)) and len(x) == 0:
            continue
        out.append(x)
    return out

def is_numeric_palindrome(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def most_common_word_length(words):
    counts = {}
    for w in words:
        counts[len(w)] = counts.get(len(w), 0) + 1
    best = max(counts.values())
    cands = [l for l, c in counts.items() if c == best]
    return min(cands)

def is_semiprime(n):
    if n < 4:
        return False
    count = 0
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            temp //= d
            count += 1
            if count > 2:
                return False
        d += 1
    if temp > 1:
        count += 1
    return count == 2

def digits_in_factorial(n):
    f = 1
    for i in range(2, n + 1):
        f *= i
    return len(str(f))

def are_all_rotations_equal(lst):
