        return True
    return all(x == lst[0] for x in lst)

def remove_every_kth_starting_at(lst, k, start):
    if k <= 0:
        return lst[:]
    remove_set = set(range(start, len(lst), k))
    return [x for idx, x in enumerate(lst) if idx not in remove_set]

def remove_punctuation(s):
    import string
    return ''.join(ch for ch in s if ch not in string.punctuation)

def nth_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    num = 1
    while count < n:
        num += 1
        if isp(num):
            count += 1
    return num

def justify_line(words, width):
    if len(words) == 1:
        return words[0].ljust(width)
    total_chars = sum(len(w) for w in words)
    total_spaces = width - total_chars
    gaps = len(words) - 1
    base, extra = divmod(total_spaces, gaps)
    line = ''
    for i, w in enumerate(words[:-1]):
        line += w + ' ' * (base + (1 if i < extra else 0))
    line += words[-1]
    return line

def list_diff_multiset(a, b):
    from collections import Counter
    to_remove = Counter(b)
    out = []
    for x in a:
        if to_remove.get(x, 0) > 0:
            to_remove[x] -= 1
        else:
            out.append(x)
    return out

def count_divisor_pairs(n):
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
        i += 1
    return count

def words_appearing_once(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return sorted(w for w, c in counts.items() if c == 1)
